#include "study_observer.h"
#define main original_mnist_entry
#include "instrumented_native/main.cu"
#undef main
namespace study {
std::vector<Layer*>layers(){return{&l_input,&l_c1,&l_s1,&l_f};}
std::vector<std::pair<float*,int>>buffers(Layer*l){return{{l->output,l->O},{l->preact,l->O},{l->bias,l->N},{l->weight,l->M*l->N},{l->d_output,l->O},{l->d_preact,l->O},{l->d_weight,l->M*l->N}};}
void snapshot(int kind,int step,int label,int prediction){auto&s=state();int header[]={kind,step,label,prediction};write(s.science,header,16);for(int x:header)s.output.push_back(x);int layer=0;for(auto*l:layers()){int field=0;for(auto b:buffers(l)){if(b.second&&!(layer==0&&(field==4||field==5))){auto a=read(b.first,b.second);write(s.science,a.data(),a.size()*4);for(float x:a)s.output.push_back(x);}field++;}layer++;}}
void before_upload(){auto&s=state();if(s.capture&&s.pending){Pause pause;snapshot(1,s.oldstep,s.oldlabel,-1);s.pending=false;}}
void after_upload(float*p,int n){auto&s=state();if(s.capture){Pause pause;auto a=read(p,n);for(float x:a)s.prefix.push_back(x);}}
void forward_capture(){auto&s=state();if(s.capture){Pause pause;snapshot(0,s.step,s.label,-1);s.pending=true;s.oldstep=s.step;s.oldlabel=s.label;}}
void test_capture(unsigned prediction){auto&s=state();if(s.capture){Pause pause;snapshot(2,s.step,s.label,prediction);}}
void final_physical(){auto&s=state();Pause pause;std::vector<std::pair<int,std::pair<void*,Allocation>>>ordered;for(auto&a:s.live)ordered.push_back({a.second.id,a});std::sort(ordered.begin(),ordered.end(),[](auto&a,auto&b){return a.first<b.first;});for(auto&a:ordered){auto q=a.second.second;std::vector<unsigned char>raw(q.n+512);check(cudaMemcpy(raw.data(),q.base,raw.size(),cudaMemcpyDeviceToHost));uint64_t h[]={uint64_t(q.id),uint64_t(q.n)};write(s.physical,h,16);write(s.physical,raw.data(),raw.size());for(int j=0;j<256;j++)s.correct&=raw[j]==0xa7&&raw[q.n+256+j]==0xa7;}}
}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("dataset folder and persistent evidence folder required");auto&s=study::state();s.folder=argv[2];std::filesystem::create_directories(s.folder);if(loaddata(argv[1]))throw std::runtime_error("exact MNIST IDX load failed");if(train_cnt!=100||test_cnt!=20)throw std::runtime_error("expected balanced100train20test");std::vector<float>initial;for(auto*l:study::layers()){for(auto b:{std::pair<float*,int>{l->bias,l->N},std::pair<float*,int>{l->weight,l->M*l->N}}){auto v=study::read(b.first,b.second);initial.insert(initial.end(),v.begin(),v.end());}}{std::ofstream f(s.folder+"/source_initial_parameters.bin",std::ios::binary);study::write(f,initial.data(),initial.size()*4);}
for(int trial=0;trial<=5;trial++){s.capture=trial>0;s.trial=trial;s.pending=false;s.correct=true;s.seconds=0;s.prefix.clear();s.output.clear();size_t off=0;for(auto*l:study::layers()){for(auto b:{std::pair<float*,int>{l->bias,l->N},std::pair<float*,int>{l->weight,l->M*l->N}}){if(b.second)study::check(cudaMemcpy(b.first,initial.data()+off,b.second*4,cudaMemcpyHostToDevice));off+=b.second;}}study::check(cudaDeviceSynchronize());if(s.capture){for(auto*l:study::layers())for(auto b:{std::pair<float*,int>{l->bias,l->N},std::pair<float*,int>{l->weight,l->M*l->N}}){auto a=study::read(b.first,b.second);for(float x:a)s.prefix.push_back(x);}for(unsigned i=0;i<train_cnt;i++)s.prefix.push_back(train_set[i].label);for(unsigned i=0;i<test_cnt;i++)s.prefix.push_back(test_set[i].label);s.science.open(s.folder+"/cuda_trial"+std::to_string(trial)+".science.bin",std::ios::binary);s.physical.open(s.folder+"/cuda_trial"+std::to_string(trial)+".physical.bin",std::ios::binary);}
s.tick=std::chrono::steady_clock::now();s.running=true;learn(2);test();study::check(cudaDeviceSynchronize());s.seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-s.tick).count();s.running=false;if(!trial)continue;study::final_physical();s.science.close();s.physical.close();size_t prefix=s.prefix.size();s.prefix.insert(s.prefix.end(),s.output.begin(),s.output.end());for(double x:s.prefix)s.correct&=std::isfinite(x);std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);study::write(f,s.prefix.data(),s.prefix.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"input_prefix_values\":%zu,\"timing_region\":\"complete_source_learn2_test_pipeline_observer_split_context_completion\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,s.seconds,s.correct?"true":"false",s.prefix.size(),prefix,path.c_str(),s.prefix.size());fflush(stdout);if(!s.correct)return 1;}
free(train_set);free(test_set);return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
